a<-grep('^--file=',commandArgs(),value=TRUE);root<-dirname(normalizePath(sub('^--file=','',a[1])));r<-function(p)read.csv(file.path(root,p),check.names=FALSE)
s<-r('panel_h/inputs/all_features_GAM_significance.csv');h<-r('panel_c/tables/heatmap_rowZ.csv');dq<-r('panel_d/tables/GAM_significant_annotated_query_features.csv');ch<-r('panel_h/tables/P41_choline_pathway_Osi_vs_OsiTCD_significance.csv');ann<-r('panel_h/inputs/annotated_feature_KEGG_pathway_mapping.csv');cur<-r('panel_h/tables/pathway_GAM_curves_and_CI.csv');grid<-r('panel_c/tables/GAM_pseudotime_grid.csv');delta<-0
for(pair in list(c('Osi','Osi'),c('TCDOsi','TCD+Osi'))){m<-r(paste0('panel_c/tables/GAM_fitted_',pair[1],'.csv'));for(id in unique(cur$feature_id)){z<-cur[cur$feature_id==id&cur$condition==pair[2],];stopifnot(nrow(z)==160);delta<-max(delta,abs(z$pseudotime-grid$pseudotime),abs(as.numeric(m[m$feature_id==id,-1])-z$fit))}}
pcols<-c('association_p_Osi','association_p_TCDOsi','pattern_pvalue','startEnd_p_Osi','startEnd_p_TCDOsi');qcols<-c('association_BH_FDR_Osi','association_BH_FDR_TCDOsi','pattern_BH_FDR','startEnd_BH_FDR_Osi','startEnd_BH_FDR_TCDOsi');qerr<-max(vapply(seq_along(pcols),function(i)max(abs(p.adjust(s[[pcols[i]]],'BH',n=nrow(s))-s[[qcols[i]]])),numeric(1)))
checks<-data.frame(check=c('Identical C D H all-feature statistics','All feature BH recomputation','Heatmap IDs equal significant annotations','KEGG query equals heatmap','Heatmap FDR equals full-family source','All pathway table FDR equals source','Selected pathway dense curves agree for both groups','Independent all-feature GAM refit agrees'),passed=c(identical(s,r('panel_c/inputs/all_features_GAM_significance.csv'))&&identical(s,r('panel_d/inputs/all_features_GAM_significance.csv')),qerr<1e-12,setequal(h$feature_id,intersect(ann$feature_id,s$feature_id[s$association_BH_FDR_Osi<.05])),setequal(h$feature_id,dq$feature_id),max(abs(h$q_value-s$association_BH_FDR_Osi[match(h$feature_id,s$feature_id)]))<1e-12,max(abs(ch$association_BH_FDR_Osi-s$association_BH_FDR_Osi[match(ch$feature_id,s$feature_id)]))<1e-12,delta<1e-9,max(r('panel_c/tables/GAM_refit_validation.csv')$max_p_difference)<1e-7))
write.csv(checks,file.path(root,'statistical_consistency_validation.csv'),row.names=FALSE);print(checks);cat('maximum curve error',delta,'\n');stopifnot(all(checks$passed))
